CREATE TABLE IF NOT EXISTS users (id VARCHAR(32) PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, phone VARCHAR(40) NOT NULL DEFAULT '', delivery_profile TEXT, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'customer', active INTEGER NOT NULL DEFAULT 1, auth_version INTEGER NOT NULL DEFAULT 1, created_at VARCHAR(19) NOT NULL, updated_at VARCHAR(19) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS categories (id VARCHAR(32) PRIMARY KEY, parent_id VARCHAR(32), name VARCHAR(120) NOT NULL, slug VARCHAR(160) NOT NULL UNIQUE, description TEXT NOT NULL, image TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0, created_at VARCHAR(19) NOT NULL, updated_at VARCHAR(19) NOT NULL, FOREIGN KEY(parent_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS products (id VARCHAR(32) PRIMARY KEY, category_id VARCHAR(32), name VARCHAR(160) NOT NULL, slug VARCHAR(180) NOT NULL UNIQUE, short_description TEXT NOT NULL, description TEXT NOT NULL, price INTEGER NOT NULL, sale_price INTEGER, images TEXT NOT NULL, stock INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, featured INTEGER NOT NULL DEFAULT 0, sort_order INTEGER NOT NULL DEFAULT 0, created_at VARCHAR(19) NOT NULL, updated_at VARCHAR(19) NOT NULL, FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS delivery_areas (id VARCHAR(32) PRIMARY KEY, area_key VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, governorate VARCHAR(120) NOT NULL, district VARCHAR(120) NOT NULL, locality VARCHAR(120) NOT NULL, identifier VARCHAR(80) NOT NULL, fee INTEGER NOT NULL, currency VARCHAR(8) NOT NULL, minimum_amount INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, notes TEXT NOT NULL, estimate VARCHAR(160) NOT NULL, created_at VARCHAR(19) NOT NULL, updated_at VARCHAR(19) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS delivery_mutex (id VARCHAR(32) PRIMARY KEY) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS orders (id VARCHAR(32) PRIMARY KEY, reference VARCHAR(30) NOT NULL UNIQUE, user_id VARCHAR(32), customer_name VARCHAR(120) NOT NULL, email VARCHAR(254) NOT NULL, phone VARCHAR(40) NOT NULL, address TEXT NOT NULL, city VARCHAR(120) NOT NULL, notes TEXT NOT NULL, internal_notes TEXT NOT NULL, subtotal INTEGER NOT NULL, delivery_area_id VARCHAR(32), delivery_snapshot TEXT, offer_discount INTEGER NOT NULL DEFAULT 0, offer_snapshot TEXT, welcome_discount INTEGER NOT NULL DEFAULT 0, welcome_promotion_id VARCHAR(32), welcome_percentage INTEGER NOT NULL DEFAULT 0, delivery_fee INTEGER NOT NULL, tax INTEGER NOT NULL, total INTEGER NOT NULL, currency VARCHAR(8) NOT NULL, status VARCHAR(30) NOT NULL, payment_method VARCHAR(30) NOT NULL, payment_status VARCHAR(30) NOT NULL, idempotency_key VARCHAR(64) NOT NULL UNIQUE, stock_released INTEGER NOT NULL DEFAULT 0, created_at VARCHAR(19) NOT NULL, updated_at VARCHAR(19) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL, CONSTRAINT fk_order_delivery FOREIGN KEY(delivery_area_id) REFERENCES delivery_areas(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS order_items (id VARCHAR(32) PRIMARY KEY, order_id VARCHAR(32) NOT NULL, product_id VARCHAR(32), product_name VARCHAR(160) NOT NULL, unit_price INTEGER NOT NULL, quantity INTEGER NOT NULL, image TEXT NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS reviews (id VARCHAR(32) PRIMARY KEY, user_id VARCHAR(32), product_id VARCHAR(32), name VARCHAR(120) NOT NULL, rating INTEGER NOT NULL, comment TEXT NOT NULL, status VARCHAR(20) NOT NULL, featured INTEGER NOT NULL DEFAULT 0, created_at VARCHAR(19) NOT NULL, updated_at VARCHAR(19) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS settings (id VARCHAR(32) PRIMARY KEY, value TEXT NOT NULL, updated_at VARCHAR(19) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS homepage_sections (id VARCHAR(32) PRIMARY KEY, title VARCHAR(200) NOT NULL, description TEXT NOT NULL, image TEXT NOT NULL, cta_text VARCHAR(80) NOT NULL, cta_url TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0, updated_at VARCHAR(19) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS pages (id VARCHAR(32) PRIMARY KEY, slug VARCHAR(160) NOT NULL UNIQUE, title VARCHAR(200) NOT NULL, body TEXT NOT NULL, meta_title VARCHAR(200) NOT NULL, meta_description TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, updated_at VARCHAR(19) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS navigation (id VARCHAR(32) PRIMARY KEY, label VARCHAR(80) NOT NULL, url TEXT NOT NULL, location VARCHAR(20) NOT NULL, active INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS promotions (id VARCHAR(32) PRIMARY KEY, title VARCHAR(200) NOT NULL, description TEXT NOT NULL, image TEXT NOT NULL, cta_text VARCHAR(80) NOT NULL, cta_url TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0, updated_at VARCHAR(19) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS messages (id VARCHAR(32) PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(254) NOT NULL, message TEXT NOT NULL, status VARCHAR(20) NOT NULL, created_at VARCHAR(19) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS audit_log (id VARCHAR(32) PRIMARY KEY, user_id VARCHAR(32), action VARCHAR(60) NOT NULL, entity VARCHAR(40) NOT NULL, entity_id VARCHAR(64) NOT NULL, created_at VARCHAR(19) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS rate_limits (id VARCHAR(32) PRIMARY KEY, bucket VARCHAR(64) NOT NULL, created_at VARCHAR(19) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS welcome_promotions (id VARCHAR(32) PRIMARY KEY, user_id VARCHAR(32) NOT NULL UNIQUE, email_key VARCHAR(64) NOT NULL UNIQUE, percentage INTEGER NOT NULL, activated_at VARCHAR(19) NOT NULL, expires_at VARCHAR(19) NOT NULL, status VARCHAR(20) NOT NULL, redeemed_order_id VARCHAR(32) UNIQUE, redeemed_at VARCHAR(19), discount_amount INTEGER NOT NULL DEFAULT 0, reason VARCHAR(60) NOT NULL DEFAULT '', FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS offers (id VARCHAR(32) PRIMARY KEY, name VARCHAR(160) NOT NULL, title VARCHAR(200) NOT NULL, description TEXT NOT NULL, image TEXT NOT NULL, cta_text VARCHAR(80) NOT NULL, cta_url TEXT NOT NULL, discount_type VARCHAR(20) NOT NULL, discount_value INTEGER NOT NULL, scope VARCHAR(20) NOT NULL, starts_at VARCHAR(19) NOT NULL, ends_at VARCHAR(19), state VARCHAR(20) NOT NULL, popup_enabled INTEGER NOT NULL, frequency VARCHAR(20) NOT NULL, priority INTEGER NOT NULL DEFAULT 0, minimum_amount INTEGER NOT NULL DEFAULT 0, maximum_discount INTEGER NOT NULL DEFAULT 0, total_limit INTEGER NOT NULL DEFAULT 0, customer_limit INTEGER NOT NULL DEFAULT 0, members_only INTEGER NOT NULL DEFAULT 0, deleted INTEGER NOT NULL DEFAULT 0, created_by VARCHAR(32), created_at VARCHAR(19) NOT NULL, updated_at VARCHAR(19) NOT NULL, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS offer_products (offer_id VARCHAR(32) NOT NULL, product_id VARCHAR(32) NOT NULL, excluded INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(offer_id,product_id), FOREIGN KEY(offer_id) REFERENCES offers(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS offer_categories (offer_id VARCHAR(32) NOT NULL, category_id VARCHAR(32) NOT NULL, PRIMARY KEY(offer_id,category_id), FOREIGN KEY(offer_id) REFERENCES offers(id) ON DELETE CASCADE, FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS offer_redemptions (id VARCHAR(32) PRIMARY KEY, offer_id VARCHAR(32) NOT NULL, order_id VARCHAR(32) NOT NULL, user_id VARCHAR(32), customer_key VARCHAR(64) NOT NULL, amount INTEGER NOT NULL, snapshot TEXT NOT NULL, created_at VARCHAR(19) NOT NULL, UNIQUE(offer_id,order_id), FOREIGN KEY(offer_id) REFERENCES offers(id) ON DELETE RESTRICT, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE RESTRICT, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS offer_mutex (id VARCHAR(32) PRIMARY KEY) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

